<script setup lang="ts">import { ref } from 'vue'; import PageHeader from '../components/PageHeader.vue'; const message=ref(''); async function backup(){const result=await window.sefiplanApi.createBackup(); if(result) message.value=`Respaldo creado en ${result.path}`;} async function restore(){const result=await window.sefiplanApi.restoreBackup();if(result?.restored)message.value=`Información restaurada. Respaldo previo: ${result.automaticBackupPath}`;}</script>
<template><PageHeader title="Respaldos" description="Protege la base local, la configuración y las reglas de la aplicación." /><section class="backup-panel"><i class="bi bi-shield-check" aria-hidden="true" /><div><h2>Crear respaldo completo</h2><p>Genera un archivo ZIP local con una copia consistente de SQLite y un manifiesto de versión.</p><div class="d-flex gap-2 flex-wrap"><button class="btn btn-primary" type="button" @click="backup"><i class="bi bi-archive" /> Crear respaldo</button><button class="btn btn-outline-danger" type="button" @click="restore"><i class="bi bi-arrow-counterclockwise" /> Restaurar respaldo</button></div><p v-if="message" class="success-message" role="status">{{ message }}</p></div></section></template>
